type View='home'|'portfolio'|'search'|'wishlist'|'social'|'profile';
type SearchScreen='filters'|'sets'|'set';
type RangeKey='1D'|'7D'|'1M'|'3M'|'6M'|'MAX';
type CategoryGroup={key:string;rawName:string;name:string;items:Item[];cover:string};
type SetGroup={key:string;rawName:string;name:string;items:Item[];cover:string;collectionId?:string};
type EditTarget={kind:'category';key:string;rawName:string;name:string}|{kind:'set';key:string;rawName:string;name:string;collectionId?:string}|{kind:'product';itemId:string};

type Props={status:string;profileName:string;data:StoreData;update:(next:StoreData)=>void;config:CloudConfig|null;session:Session|null};

const ranges:RangeKey[]=['1D','7D','1M','3M','6M','MAX'];
const sortOptions=['Price: Low to High','Price: High to Low','Name: A to Z','Name: Z to A','Newest Added'];
const nowIso=()=>new Date().toISOString();
const slug=(v:string)=>v.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const categoryKey=(name:string)=>`mobile-category::${slug(name)}`;
const setKey=(category:string,name:string)=>`mobile-set::${slug(category)}::${slug(name)}`;
function groupMeta(data:StoreData,key:string){return data.libraryGroups?.[key]||{}}
function groupName(data:StoreData,key:string,fallback:string){return groupMeta(data,key).name?.trim()||fallback}
function groupCover(data:StoreData,key:string){return groupMeta(data,key).coverImage||''}
function itemCollection(data:StoreData,item:Item){return data.collections.find(c=>c.id===item.collectionId)}
function itemCategory(data:StoreData,item:Item){return itemLibraryLine(item,itemCollection(data,item))||'Other'}
function derivedSetName(data:StoreData,item:Item){const c=itemCollection(data,item);if(c&&c.id!=='unlabeled-system'&&!/^unlabeled$/i.test(c.name))return c.name;const f=item.customFields||{};return f.Set||f.Series||f.Collection||item.identity?.series||item.identity?.brand||item.category||'Unsorted'}
function productNumber(item:Item){return item.customFields?.Number||item.customFields?.number||item.identity?.collectorNumber||item.identity?.sku||''}
function ownedQty(item:Item){return item.status==='owned'?item.quantity:0}
function holdingValue(item:Item){return item.status==='owned'?item.currentValue*item.quantity:0}
function itemChange(item:Item){const pts=(item.priceHistory||[]).filter(p=>p.kind!=='sale').slice(-2);if(pts.length<2)return{delta:0,pct:0};const a=pts[0].value,b=pts[1].value,delta=b-a;return{delta,pct:a?delta/a*100:0}}
function fmtChange(delta:number,pct:number){const s=delta>=0?'+':'';return `${s}${money(delta)} (${s}${pct.toFixed(2)}%)`}
function isWishlisted(item:Item){return item.status==='wishlist'||item.customFields?.__wishlist==='true'}
function fileDataUrl(file:File){return new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(r.error);r.readAsDataURL(file)})}
function rangeMs(range:RangeKey){return range==='1D'?864e5:range==='7D'?6048e5:range==='1M'?2592e6:range==='3M'?7776e6:range==='6M'?15552e6:Infinity}
function totalSnapshot(values:Record<string,number>){return Object.values(values||{}).reduce((a,b)=>a+(Number(b)||0),0)}
function chartPoints(data:StoreData,current:number,range:RangeKey){const cutoff=Date.now()-rangeMs(range);let pts=(data.history||[]).map(h=>({date:h.date,value:totalSnapshot(h.values)})).filter(p=>range==='MAX'||Date.parse(p.date)>=cutoff);const now={date:nowIso(),value:current};if(!pts.length)pts=[{date:new Date(Date.now()-864e5).toISOString(),value:current},now];else if(pts.at(-1)!.date.slice(0,10)===now.date.slice(0,10))pts[pts.length-1]=now;else pts.push(now);if(pts.length===1)pts.unshift({date:new Date(Date.parse(pts[0].date)-864e5).toISOString(),value:pts[0].value});return pts}
function currentMonth(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function defaultPrefs(data:StoreData){return data.preferences||{accentColor:'#ff1f2d',density:'comfortable' as const,cardSize:'standard' as const,reducedMotion:false}}

