  const sets=useMemo<SetGroup[]>(()=>{if(!selectedCategory)return[];const category=categories.find(c=>c.rawName===selectedCategory);const map=new Map<string,SetGroup>();for(const item of category?.items||[]){const c=itemCollection(data,item);if(c&&c.id!=='unlabeled-system'&&!/^unlabeled$/i.test(c.name)){const key=`collection::${c.id}`,e=map.get(key);if(e)e.items.push(item);else map.set(key,{key,rawName:c.name,name:c.name,items:[item],cover:c.coverImage||'',collectionId:c.id})}else{const raw=derivedSetName(data,item),key=setKey(selectedCategory,raw),e=map.get(key);if(e)e.items.push(item);else map.set(key,{key,rawName:raw,name:groupName(data,key,raw),items:[item],cover:groupCover(data,key)})}}for(const c of data.collections){if(c.id!=='unlabeled-system'&&c.libraryLine===selectedCategory&&!map.has(`collection::${c.id}`))map.set(`collection::${c.id}`,{key:`collection::${c.id}`,rawName:c.name,name:c.name,items:[],cover:c.coverImage||'',collectionId:c.id})}return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name))},[data,categories,selectedCategory]);
