  const moveWishlist=(id:string)=>patch(d=>({...d,items:d.items.map(i=>i.id===id?{...i,status:'wishlist',quantity:Math.max(1,i.quantity),customFields:Object.fromEntries(Object.entries(i.customFields||{}).filter(([k])=>k!=='__wishlist')),updatedAt:nowIso()}:i)}));
