  const createProduct=()=>{const id=crypto.randomUUID(),collectionId=data.collections.find(c=>c.id!=='unlabeled-system')?.id||'';const item:Item={id,collectionId,name:'New Product',category:'Other',status:'owned',purchasePrice:0,currentValue:0,quantity:1,image:'',condition:'',purchaseDate:new Date().toISOString().slice(0,10),location:'',notes:'',customFields:{},identity:{marketCategory:'other'},createdAt:nowIso(),updatedAt:nowIso()};update({...data,items:[...data.items,item]});window.setTimeout(()=>setEditTarget({kind:'product',itemId:id}),0)};
